param([Parameter(Mandatory=$true)][string]$CandidateDirectory,[string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks",[string]$ModelRepo="D:\Dev\LotSizingDataModel",[double]$ObjectiveAbsoluteTolerance=0.000001,[double]$ObjectiveRelativeTolerance=0.000000001)
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop";function StopGate([string]$Message){throw $Message};if(-not(Test-Path -LiteralPath $CandidateDirectory -PathType Container)){StopGate "Candidate directory missing."};$metadataPath=Join-Path $CandidateDirectory "candidate.json";if(-not(Test-Path -LiteralPath $metadataPath -PathType Leaf)){StopGate "candidate.json missing."};$metadata=Get-Content -LiteralPath $metadataPath -Raw|ConvertFrom-Json;foreach($name in @("familyId","canonicalInstanceId","declaredObjective","sourceType")){if($null-eq$metadata.$name-or[string]::IsNullOrWhiteSpace([string]$metadata.$name)){StopGate("Required candidate field missing: "+$name)}};if($metadata.sourceType -ne "COMPLETE_SOLUTION"){StopGate "Only COMPLETE_SOLUTION candidates can enter the Checker gate; literature values use evidence intake."};if([string]::IsNullOrWhiteSpace([string]$metadata.solutionFile)){StopGate "solutionFile missing."};$solution=Join-Path $CandidateDirectory ([string]$metadata.solutionFile);if(-not(Test-Path -LiteralPath $solution -PathType Leaf)){StopGate "Declared solution file missing."};$checker=Join-Path $ModelRepo "LotSizingDataModel.Checker.Cli\LotSizingDataModel.Checker.Cli.csproj";if(-not(Test-Path -LiteralPath $checker -PathType Leaf)){StopGate "Checker project missing."};$stamp=Get-Date -Format "yyyyMMdd-HHmmss";$report=Join-Path $CandidateDirectory ("checker-report-"+$stamp);New-Item -ItemType Directory -Path $report -Force|Out-Null;& dotnet build $checker -c Release --nologo;if($LASTEXITCODE -ne 0){StopGate "Checker build failed."};& dotnet run --project $checker -c Release --no-build -- $CandidateDirectory --level full --output $report --no-update-known-result --no-promote-known-result --no-progress --objective-absolute-tolerance $ObjectiveAbsoluteTolerance --objective-relative-tolerance $ObjectiveRelativeTolerance;$code=$LASTEXITCODE;$decision=[ordered]@{familyId=$metadata.familyId;canonicalInstanceId=$metadata.canonicalInstanceId;candidateDirectory=$CandidateDirectory;candidateSha256=(Get-FileHash -LiteralPath $solution -Algorithm SHA256).Hash;declaredObjective=$metadata.declaredObjective;checkerExitCode=$code;checkerReport=$report;decision=$(if($code -eq 0){"CHECKER_VERIFIED_FEASIBLE"}elseif($code -eq 1){"REJECTED_BY_CHECKER"}else{"CHECKER_EXECUTION_ERROR"});promotionApplied=$false;optimalityPromoted=$false;timestampUtc=[DateTime]::UtcNow.ToString("o")};$decision|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $CandidateDirectory ("trust-gate-decision-"+$stamp+".json")) -Encoding UTF8;if($code -ne 0){exit $code};Write-Host "CANDIDATE_TRUST_GATE_VALID";Write-Host "STATUS|CHECKER_VERIFIED_FEASIBLE";Write-Host "PROMOTION_APPLIED|False";Write-Host "OPTIMALITY_PROMOTED|False"
